# Generated by build.py from recipe.yml for recipe pop3-drain-a-maildrop. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'order1.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Order 1 shipped`n`nYour first order is on its way.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'order2.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Order 2 shipped`n`nYour second order is on its way.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'order3.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Order 3 shipped`n`nYour third order is on its way.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'shop@example.com:shoppass', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/', 'imap://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[1-3].eml" smtp://127.0.0.1:8080/example.com --next -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt bob@example.com -T "order[1-3].eml" smtp://127.0.0.1:8080/example.com
curl.exe -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "LIST 3" pop3://127.0.0.1:8081/
curl.exe -sS --retry 10 --retry-all-errors --retry-delay 1 -u bob@example.com:bobpass -X "LIST 3" pop3://127.0.0.1:8081/
try { curl.exe -sS -u ann@example.com:annpass -o "msg#1.eml" "pop3://127.0.0.1:8081/[1-3]" --next -sS -u ann@example.com:annpass -X DELE "pop3://127.0.0.1:8081/[1-3]" } finally { Stop-Process $server0 }
